import{_ as t,o as a,c as o,ao as r}from"./chunks/framework.B4BvXMeI.js";const p=JSON.parse('{"title":"API stability","description":"","frontmatter":{},"headers":[],"relativePath":"api-stability.md","filePath":"api-stability.md","lastUpdated":null}'),i={name:"api-stability.md"};function s(n,e,d,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="API-stability" tabindex="-1">API stability <a class="header-anchor" href="#API-stability" aria-label="Permalink to &quot;API stability {#API-stability}&quot;">​</a></h1><p><em>The stability promise of the v0.7 line, stated precisely. Machine-checked by the package API-stability gate, which classifies <strong>every</strong> exported name into exactly one tier and fails if a new export appears unclassified, a stable name vanishes, or a tier changes without a reviewed edit.</em></p><h2 id="The-promise" tabindex="-1">The promise <a class="header-anchor" href="#The-promise" aria-label="Permalink to &quot;The promise {#The-promise}&quot;">​</a></h2><p><em>Versioning follows the R twin&#39;s parity level. Julia General registration remains deferred; a formal SemVer <code>1.0</code> will be coordinated with the twin. Julia&#39;s 0.x convention allows minor-version breakage; this page plus the test gate are the promise that we will not use that allowance on the Stable tier.</em></p><p>From <code>v0.7.0</code>, names in the <strong>Stable</strong> tier — the <code>bf()</code>/<code>drm()</code> grammar, the fourteen family constructors, the structured-effect markers, and the accessor/inference/plotting surface — keep their names, meanings, and conventions across the <code>0.7.x</code> line and beyond. The conventions are drmTMB&#39;s: scale is <strong><code>sigma</code></strong> (never <code>tau</code>), the bivariate residual correlation is <strong><code>rho12</code></strong>, meta-analysis is <code>gaussian()</code> + <strong><code>meta_V</code></strong>. Breaking any of these is a co-versioned major event decided with the twin, never a quiet 0.x bump.</p><h2 id="The-three-tiers" tabindex="-1">The three tiers <a class="header-anchor" href="#The-three-tiers" aria-label="Permalink to &quot;The three tiers {#The-three-tiers}&quot;">​</a></h2><p><strong>Stable</strong> — the promise above. The stable API contract is the authoritative list and is checked against the implementation.</p><p><strong>Experimental — exported, usable, exempt.</strong> These work today and are tested, but their shape may change between releases, and each carries its reason:</p><ul><li><p><strong><code>r2_constant_sigma</code></strong> — the number is settled (it is the ordinary <code>lm()</code> R², and equals it exactly on a constant-σ Gaussian fit), but the REFUSALS are the part a caller programs against, and they may widen. In particular a <em>marginal</em> or <em>conditional</em> R² for random-effect fits (Nakagawa &amp; Schielzeth) would reshape this surface, and that decision has not been taken;</p></li><li><p>the <strong>R bridge</strong> (<code>drm_bridge</code>, <code>drm_bridge_inference</code>, <code>drm_listwise</code>) — it is experimental, so its accepted models and returned details may change;</p></li><li><p>the <strong>cross-family surface</strong> (<code>mf_*</code>, <code>associate_pairs</code>, <code>latent_normal</code>, <code>association</code>, <code>PairAssociation</code>, <code>integration_diagnostics</code>) — it has a deliberately narrow documented scope;</p></li><li><p>the <strong>penalized-MAP surface</strong> (<code>drm_phylo_penalty*</code>, <code>PhyloPenalty</code>, <code>PhyloCorPenaltyNeedsTwoSD</code>) and <strong>bivariate meta</strong> (<code>meta_vcov_bivariate</code>) — newer surfaces whose ergonomics are still settling;</p></li><li><p>the <strong>VA/ELBO marginal</strong> (<code>marginal = :VA</code>) — reachable through stable <code>drm()</code> but Experimental-labelled on its own pages; its behaviour and coverage may change between releases;</p></li><li><p>the <strong>prepared joint missing-predictor surface</strong> (<code>PreparedJointModel</code>, <code>prepared_joint_model</code>, <code>fit_prepared_joint</code>, <code>mi</code>, and related result and summary types) — implemented and tested, while formula and bridge ergonomics continue to settle.</p></li></ul><p><strong>Engine</strong> — the computational spine (<code>AugProblem</code>, <code>make_problem</code>, <code>fit_q4_sparse_tmb</code>, <code>estep_mode</code>, the <code>coevo_*</code> and <code>fz_*</code> families, tree utilities, packers). Exported for advanced scripts and benchmarks; stable in practice but <strong>not</strong> part of the promise, the same way a language&#39;s internals are not.</p><h2 id="What-the-promise-does-and-does-not-cover" tabindex="-1">What the promise does and does not cover <a class="header-anchor" href="#What-the-promise-does-and-does-not-cover" aria-label="Permalink to &quot;What the promise does and does not cover {#What-the-promise-does-and-does-not-cover}&quot;">​</a></h2><p>It covers names, argument meanings, and return conventions on the Stable tier. It does <strong>not</strong> cover: numerical trajectories (an optimiser or tolerance improvement may move estimates within documented accuracy), the Experimental and Engine tiers, or interval <em>coverage</em> — interval claims throughout this package are <strong>capability parity, not coverage</strong>; the ledger&#39;s <code>coverage_claimed</code> fences are permanent documented boundaries.</p><h2 id="Deliberate-exclusions-at-v0.7.0" tabindex="-1">Deliberate exclusions at v0.7.0 <a class="header-anchor" href="#Deliberate-exclusions-at-v0.7.0" aria-label="Permalink to &quot;Deliberate exclusions at v0.7.0 {#Deliberate-exclusions-at-v0.7.0}&quot;">​</a></h2><ul><li><p><strong>Bivariate Student structured markers</strong> (<code>phylo</code>/<code>relmat</code>/<code>animal</code>/<code>spatial</code> on <code>Student()</code> bivariate) are <strong>outside</strong> the frozen surface — matching drmTMB, whose own <code>biv_student()</code> defers structured effects. Bivariate <strong>LogNormal</strong> structured markers are inside: they delegate to the exact/q4 Gaussian engines on <code>log(y)</code> and are tested.</p></li><li><p>The prepared joint missing-predictor API is available as an Experimental post-v0.7 surface. Its inclusion here does not widen the Stable-tier promise.</p></li></ul>',14)])])}const g=t(i,[["render",s]]);export{p as __pageData,g as default};
